const performance=document.createElement('details');performance.id='deltaPerformance';performance.className='market-section';performance.innerHTML='<summary>Quick ledger check · optional</summary><p><a href="/learnings">Open Performance &amp; Learnings →</a> for your calendar and full history.</p><h2>My Delta performance</h2><p>Real account ledger · separate from demo trading.</p><div class="market-controls"><label>Period<select id="performanceDays"><option value="7">Last 7 days</option><option value="30" selected>Last 30 days</option><option value="90">Last 90 days</option></select></label><button id="loadPerformance">Refresh performance</button></div><p id="performanceStatus" role="status">Use your saved Delta connection to load performance.</p><div id="performanceResults"></div>';($('apiView')||document.querySelector('main')).append(performance);
$('loadPerformance').onclick=async()=>{const b=$('loadPerformance');if(b.disabled)return;b.disabled=true;$('performanceResults').innerHTML='';$('performanceStatus').textContent='Loading and reconciling the selected ledger period…';try{const d=await api('/api/delta-desk/performance?days='+$('performanceDays').value);$('performanceStatus').textContent='Fetched '+when(d.asOf)+' · '+when(d.start)+' to '+when(d.end);const out=$('performanceResults');if(!Array.isArray(d.currencies)||d.currencies.some(g=>!g||!Array.isArray(g.daily)))throw Error('Ledger response is incomplete. Retry or use Performance & Learnings.');$('performanceStatus').className='market-status';if(!d.currencies.length){out.textContent='No ledger entries returned for this period.';return}for(const g of d.currencies){const box=document.createElement('section');box.innerHTML='<h3>'+esc(g.asset)+'</h3><div class="metric-cards">'+[['Net trading ledger',g.net],['Product cashflow',g.tradeCashflow],['Fees / rebates (signed)',g.fees],['Funding (signed)',g.funding],['Daily realized drawdown',g.maxDrawdown],['Profitable days',g.profitableDays],['Losing days',g.losingDays],['Profitable-day %',g.profitableDayRate],['Daily profit factor',g.dailyProfitFactor]].map(([label,value])=>'<article><small>'+esc(label)+'</small><strong>'+num(value)+'</strong></article>').join('')+'</div><p>Deposits '+num(g.deposits)+' · withdrawals '+num(g.withdrawals)+' · other ledger entries '+num(g.other)+' (excluded).</p>'+table(['Day (IST)','Net trading ledger','Cumulative'],g.daily.map(r=>[r.date,num(r.net),num(r.cumulative)]));out.append(box)}const note=document.createElement('p');note.textContent=d.method;out.append(note)}catch(e){$('performanceStatus').textContent=e.message;$('performanceStatus').className='market-error'}finally{b.disabled=false}};
